// Sidebar.jsx
import React, { useEffect, useRef, useState } from 'react';
import { Accordion, Alert, Badge, Button, Card, Col, Form, InputGroup, Row } from 'react-bootstrap';

const TOPIC_LABEL_STORAGE_KEY = 'topic-label-overrides-v1';
const TOPIC_NAME_MAP = {
  '2': 'コンクリート構造',
  '3': '地盤改良',
  '1': 'トンネル掘削',
  '0': '免震構造',
  '9': '管理システム',
  '6': '廃棄物処理',
  '8': '建築パネル',
  '7': '空調システム',
  '11': '掘削装置',
  '12': '基礎構造',
  '31': '配管搬送',
  '10': '建築設計',
  '5': 'トンネル測量',
  '13': '電力管理',
  '16': '屋根構造',
  '14': '構造損傷',
  '24': '電磁波シールド',
  '19': '天井構造',
  '23': '音響検査',
  '15': '照明システム',
  '17': '壁面緑化',
};
const Sidebar = ({
  onApply,
  visualType,
  onVisualTypeChange,
  topicList,
  companyList,
  selectedCompanies,
  selectedTopics,
  onChangeTopic,
  onReplaceTopics,
  onChangeCompany,
}) => {
  const [inputType, setInputType] = useState(['radio', 'checkbox']);
  const [topicSearchTerm, setTopicSearchTerm] = useState('');
  const [companySearchTerm, setCompanySearchTerm] = useState('');
  const [topicManualInput, setTopicManualInput] = useState(selectedTopics[0] || '');
  const [topicNameInput, setTopicNameInput] = useState('');
  const [topicNameOverrides, setTopicNameOverrides] = useState({});
  const [activeTopicId, setActiveTopicId] = useState(selectedTopics[0] || '0');
  const [topicSwitchError, setTopicSwitchError] = useState('');
  const [isTopicEditorOpen, setIsTopicEditorOpen] = useState(false);
  const topicSearchRef = useRef(null);
  const companySearchRef = useRef(null);

  const frequentTopics = ['2', '3', '1', '0', '9', '6', '8', '7', '11', '10'];
  const frequentCompanies = [
    '鹿島建設株式会社',
    '株式会社大林組',
    '清水建設株式会社',
    '大成建設株式会社',
    '株式会社竹中工務店',
    '株式会社長谷工コーポレーション',
    '前田建設工業株式会社',
    '五洋建設株式会社',
    '株式会社熊谷組',
    '株式会社フジタ',
  ];

  useEffect(() => {
    try {
      const saved = localStorage.getItem(TOPIC_LABEL_STORAGE_KEY);
      if (saved) {
        setTopicNameOverrides(JSON.parse(saved));
      }
    } catch (error) {
      console.error('TOPIC表示名の読み込みに失敗:', error);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(TOPIC_LABEL_STORAGE_KEY, JSON.stringify(topicNameOverrides));
    } catch (error) {
      console.error('TOPIC表示名の保存に失敗:', error);
    }
  }, [topicNameOverrides]);

  useEffect(() => {
    if (selectedTopics.length === 0) {
      return;
    }
    const firstTopic = String(selectedTopics[0]);
    setActiveTopicId(firstTopic);
    setTopicManualInput(firstTopic);
  }, [selectedTopics]);

  const getTopicLabel = (topic) => {
    const topicKey = String(topic);
    return topicNameOverrides[topicKey] || TOPIC_NAME_MAP[topicKey] || `TOPIC ${topicKey}`;
  };

  const applyManualTopicChange = () => {
    const normalizedTopicId = String(topicManualInput).trim();
    if (!topicList.includes(normalizedTopicId)) {
      setTopicSwitchError(`TOPIC ${normalizedTopicId} は存在しません`);
      return;
    }
    setTopicSwitchError('');
    setActiveTopicId(normalizedTopicId);
    if (onReplaceTopics) {
      onReplaceTopics([normalizedTopicId]);
    } else {
      onChangeTopic(normalizedTopicId, 'radio');
    }
  };

  const handleSaveTopicName = () => {
    const normalizedTopicId = String(activeTopicId || '').trim();
    if (!normalizedTopicId) {
      return;
    }
    const trimmedName = topicNameInput.trim();
    if (!trimmedName) {
      return;
    }
    setTopicNameOverrides((prev) => ({
      ...prev,
      [normalizedTopicId]: trimmedName,
    }));
    setTopicNameInput('');
  };

  const handleResetTopicName = () => {
    const normalizedTopicId = String(activeTopicId || '').trim();
    if (!normalizedTopicId) {
      return;
    }
    setTopicNameOverrides((prev) => {
      const next = { ...prev };
      delete next[normalizedTopicId];
      return next;
    });
  };

  const handleRadioChange = (event) => {
    onVisualTypeChange(event.target.value);
    if (event.target.value === 'one-comp') {
      setInputType(['checkbox', 'radio']);
    } else {
      setInputType(['radio', 'checkbox']);
    }
  };

  const handleSelectAllTopics = () => {
    const allTopics = [...new Set([...topicList])];
    allTopics.forEach((topic) => {
      if (!selectedTopics.includes(topic)) {
        onChangeTopic(topic, inputType[0]);
      }
    });
  };

  const handleUnselectAllTopics = () => {
    selectedTopics.forEach((topic) => {
      onChangeTopic(topic, inputType[0]);
    });
  };

  const handleSelectAllCompanies = () => {
    const displayedCompanies = filteredCompanies.length > 0 ? filteredCompanies : companyList;
    displayedCompanies.forEach((company) => {
      if (!selectedCompanies.includes(company)) {
        onChangeCompany(company, inputType[1]);
      }
    });
  };

  const handleUnselectAllCompanies = () => {
    selectedCompanies.forEach((company) => {
      onChangeCompany(company, inputType[1]);
    });
  };

  const handleTopicSearch = (e) => {
    setTopicSearchTerm(e.target.value);
  };

  const handleCompanySearch = (e) => {
    setCompanySearchTerm(e.target.value);
  };

  const handleTopicSearchKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const matchedTopics = topicList.filter((topic) =>
        getTopicLabel(topic).toLowerCase().includes(topicSearchTerm.toLowerCase())
      );
      if (matchedTopics.length > 0) {
        onChangeTopic(matchedTopics[0], inputType[0]);
      }
      setTopicSearchTerm('');
    }
  };

  const handleCompanySearchKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const filteredCompanyResults = companyList.filter((company) =>
        company.toLowerCase().includes(companySearchTerm.toLowerCase())
      );
      if (filteredCompanyResults.length > 0) {
        onChangeCompany(filteredCompanyResults[0], inputType[1]);
      }
      setCompanySearchTerm('');
    }
  };

  const filteredTopics = topicList.filter(
    (topic) =>
      topicSearchTerm === '' ||
      getTopicLabel(topic).toLowerCase().includes(topicSearchTerm.toLowerCase()) ||
      String(topic).includes(topicSearchTerm)
  );

  const filteredCompanies = companyList.filter(
    (company) => companySearchTerm === '' || company.toLowerCase().includes(companySearchTerm.toLowerCase())
  );

  const remainingTopics = filteredTopics.filter((topic) => !frequentTopics.includes(topic));
  const remainingCompanies = filteredCompanies.filter((company) => !frequentCompanies.includes(company));

  const displayFrequentTopics = frequentTopics.filter((topic) => filteredTopics.includes(topic));
  const displayFrequentCompanies = frequentCompanies.filter((company) => filteredCompanies.includes(company));

  const showTopicSelectionButtons = visualType === 'one-comp';
  const showCompanySelectionButtons = visualType === 'one-topic';

  return (
    <div style={{ height: '100vh', padding: '10px', backgroundColor: 'bg-light' }}>
      {/* Header */}
      <Row className="bg-light text-danger font-italic" style={{ height: '5%' }}>
        <Col sm={6}>
          <h5 style={{ marginTop: '10%' }} className="text-secondary-emphasis">
            可視化条件
          </h5>
        </Col>
        <Col sm={6}>
          <Button
            id="apply"
            onClick={onApply}
            style={{ marginTop: '10%', fontSize: '1rem', padding: '0.5rem 1rem' }}
            className="w-100 rounded-pill bg-dark border-0 fw-bold"
          >
            可視化する
          </Button>
        </Col>
      </Row>

      {/* Accordion */}
      <Row className="bg-light text-danger " style={{ height: '80%' }}>
        <Accordion defaultActiveKey="0" className="my-3">
          {/* Visualization Type */}
          <Accordion.Item eventKey="0" className="white">
            <Accordion.Header>可視化タイプ</Accordion.Header>
            <Accordion.Body>
              <div className="row">
                <div className="col-6 d-flex align-items-center">
                  <input
                    type="radio"
                    id = "one-comp"
                    name="visual_type"
                    value="one-comp"
                    className="form-check-input"
                    onChange={handleRadioChange}
                    checked={visualType === "one-comp"} // デフォルトチェック
                  />
                  <label 
                  htmlFor="one-comp"
                  className="form-check-label mx-2"
                  style={{ fontSize: "14px" }}
                  >1社に注目</label>
                </div>
                <div className="col-6 d-flex align-items-center">
                  <input
                    type="radio"
                    id="one-topic"
                    name="visual_type"
                    value="one-topic"
                    className="form-check-input"
                    onChange={handleRadioChange}
                    checked={visualType === "one-topic"} // デフォルトチェック
                  />
                  <label 
                  htmlFor="one-topic"
                  className="form-check-label mx-2"
                  style={{ fontSize: "14px" }}
                  >1トピックに注目</label>
                </div>
              </div>
            </Accordion.Body>
          </Accordion.Item>

          {/* Topic Selection */}
          <Accordion.Item eventKey="1" className="white">
            <Accordion.Header>Topic</Accordion.Header>
            <Accordion.Body>
              <div className="d-flex justify-content-between align-items-center mb-2">
                <div className="small">
                  現在: <strong>{getTopicLabel(activeTopicId)}</strong>（TOPIC {activeTopicId}）
                </div>
                <Button
                  size="sm"
                  variant={isTopicEditorOpen ? 'secondary' : 'outline-primary'}
                  onClick={() => setIsTopicEditorOpen((prev) => !prev)}
                >
                  {isTopicEditorOpen ? '編集を閉じる' : '編集'}
                </Button>
              </div>

              {isTopicEditorOpen && (
                <>
                  <Card className="mb-3 border-primary-subtle">
                    <Card.Body className="py-2">
                      <div className="small text-muted mb-1">手動TOPIC切替</div>
                      <InputGroup size="sm" className="mb-2">
                        <Form.Control
                          placeholder="例: 0 / 12 / 31"
                          value={topicManualInput}
                          onChange={(e) => setTopicManualInput(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              e.preventDefault();
                              applyManualTopicChange();
                            }
                          }}
                        />
                        <Button variant="primary" onClick={applyManualTopicChange}>
                          TOPIC変更
                        </Button>
                      </InputGroup>
                      {topicSwitchError && <Alert variant="warning" className="mb-1 py-1 px-2 small">{topicSwitchError}</Alert>}
                    </Card.Body>
                  </Card>

                  <Card className="mb-3">
                    <Card.Body className="py-2">
                      <div className="small text-muted mb-1">TOPIC名の手動変更</div>
                      <InputGroup size="sm">
                        <Form.Control
                          placeholder={`TOPIC ${activeTopicId} の表示名`}
                          value={topicNameInput}
                          onChange={(e) => setTopicNameInput(e.target.value)}
                        />
                        <Button variant="outline-success" onClick={handleSaveTopicName}>保存</Button>
                        <Button variant="outline-secondary" onClick={handleResetTopicName}>リセット</Button>
                      </InputGroup>
                    </Card.Body>
                  </Card>
                </>
              )}

              {showTopicSelectionButtons && (
                <div className="d-flex justify-content-between mb-2">
                  <Button size="sm" variant="outline-primary" onClick={handleSelectAllTopics}>全選択</Button>
                  <Button size="sm" variant="outline-secondary" onClick={handleUnselectAllTopics}>全解除</Button>
                </div>
              )}
              
              {/* 頻出トピックをボタンで表示 */}
              {displayFrequentTopics.length > 0 && (
                <div className="mb-3">
                  <p className="text-muted small mb-1">よく使うトピック：</p>
                  <div className="d-flex flex-wrap gap-1">
                    {displayFrequentTopics.map((topic) => (
                      <Badge 
                        key={`badge-${topic}`}
                        bg={selectedTopics.includes(topic) ? "primary" : "light"} 
                        text={selectedTopics.includes(topic) ? "white" : "dark"}
                        style={{ cursor: 'pointer' }}
                        onClick={() => onChangeTopic(topic, inputType[0])}
                      >
                        {getTopicLabel(topic)}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
              
              <InputGroup className="mb-3">
                <Form.Control
                  placeholder="トピックを検索..."
                  value={topicSearchTerm}
                  onChange={handleTopicSearch}
                  onKeyDown={handleTopicSearchKeyDown}
                  ref={topicSearchRef}
                />
                <Button 
                  variant="outline-secondary" 
                  onClick={() => setTopicSearchTerm('')}
                >
                  クリア
                </Button>
              </InputGroup>
              
              {/* 残りのトピックをスクロール可能なエリアに表示 */}
              <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
                {remainingTopics.map((topic) => (
                  <div key={topic}>
                    <input
                      type={inputType[0]} 
                      id = {topic}
                      checked={selectedTopics.includes(topic)}
                      onChange={() => onChangeTopic(topic,inputType[0])}
                      name="topic"
                    />
                    <label htmlFor={topic}>{getTopicLabel(topic)}</label>
                  </div>
                ))}
                {filteredTopics.length === 0 && (
                  <p className="text-muted small">該当するトピックがありません</p>
                )}
              </div>
            </Accordion.Body>
          </Accordion.Item>

          {/* Company Selection */}
          <Accordion.Item eventKey="2" className="white">
            <Accordion.Header>Company</Accordion.Header>
            <Accordion.Body>
              {showCompanySelectionButtons && (
                <div className="d-flex justify-content-between mb-2">
                  <Button size="sm" variant="outline-primary" onClick={handleSelectAllCompanies}>全選択</Button>
                  <Button size="sm" variant="outline-secondary" onClick={handleUnselectAllCompanies}>全解除</Button>
                </div>
              )}
              
              {/* 頻出企業をボタンで表示 */}
              {displayFrequentCompanies.length > 0 && (
                <div className="mb-3">
                  <p className="text-muted small mb-1">よく使う企業：</p>
                  <div className="d-flex flex-wrap gap-1">
                    {displayFrequentCompanies.map((company) => (
                      <Badge 
                        key={`badge-${company}`}
                        bg={selectedCompanies.includes(company) ? "primary" : "light"} 
                        text={selectedCompanies.includes(company) ? "white" : "dark"}
                        style={{ cursor: 'pointer' }}
                        onClick={() => onChangeCompany(company, inputType[1])}
                      >
                        {company.replace('株式会社', '')}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
              
              <InputGroup className="mb-3">
                <Form.Control
                  placeholder="企業を検索..."
                  value={companySearchTerm}
                  onChange={handleCompanySearch}
                  onKeyDown={handleCompanySearchKeyDown}
                  ref={companySearchRef}
                />
                <Button 
                  variant="outline-secondary" 
                  onClick={() => setCompanySearchTerm('')}
                >
                  クリア
                </Button>
              </InputGroup>
              
              {/* 残りの企業をスクロール可能なエリアに表示 */}
              <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
                {remainingCompanies.map((company) => (
                  <div key={company}>
                    <input
                      type={inputType[1]} 
                      id = {company}
                      checked={selectedCompanies.includes(company)}
                      onChange={() => onChangeCompany(company,inputType[1])}
                      name='company'
                    />
                    <label htmlFor={company}>{company}</label>
                  </div>
                ))}
                {filteredCompanies.length === 0 && (
                  <p className="text-muted small">該当する企業がありません</p>
                )}
              </div>
            </Accordion.Body>
          </Accordion.Item>


        </Accordion>
      </Row>
    </div>
  );
};

export default Sidebar;
