import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Badge, Card, Col, Container, Form, InputGroup, ListGroup, Row, Spinner } from 'react-bootstrap';
import PlotPieA from './occupy.jsx';
import PlotPieB from './occupy-company.jsx';
import PlotPersonaComp from './persona-comp.jsx';
import PlotPersonaTopic from './persona-topic.jsx';
import PlotBarChartA from './trend-topix.jsx';
import PlotBarChartB from './trend-comp.jsx';
import ProposedVisualize from './go-anywhere.jsx';

const MAX_VISIBLE_DOCS = 120;

const Content = ({ plot, visualType, topic, company, resetApply, patentPanelWidth = 220 }) => {
  const [clickData, setClickData] = useState();
  const [clickCompanyData, setClickCompanyData] = useState();
  const [topicDocs, setTopicDocs] = useState([]);
  const [docsLoading, setDocsLoading] = useState(false);
  const [docsError, setDocsError] = useState('');
  const [docsSearchTerm, setDocsSearchTerm] = useState('');
  const activeTopicId = String(topic?.[0] ?? '');

  const handlePieChartClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickData(data);
  };

  const handlePersonaClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickCompanyData(data);
  };

  useEffect(() => {
    const fetchTopicDocs = async () => {
      if (!activeTopicId) {
        setTopicDocs([]);
        return;
      }

      setDocsLoading(true);
      setDocsError('');
      try {
        const response = await fetch(
          `${process.env.PUBLIC_URL}/data/visualize_data/patents/topic/${activeTopicId}.json`,
          { cache: 'force-cache' }
        );
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }
        const data = await response.json();
        setTopicDocs(Array.isArray(data) ? data : []);
      } catch (error) {
        setTopicDocs([]);
        setDocsError(`TOPIC ${activeTopicId} の文献読み込みに失敗しました`);
        console.error('文献リストの読み込み失敗:', error);
      } finally {
        setDocsLoading(false);
      }
    };

    fetchTopicDocs();
  }, [activeTopicId]);

  const docsFiltered = useMemo(() => {
    const term = docsSearchTerm.trim().toLowerCase();
    const base = term
      ? topicDocs.filter((doc) => {
          const inventorText = Array.isArray(doc.inventors) ? doc.inventors.join(' ') : '';
          return (
            (doc.title || '').toLowerCase().includes(term) ||
            (doc.number || '').toLowerCase().includes(term) ||
            inventorText.toLowerCase().includes(term)
          );
        })
      : topicDocs;

    return base.slice(0, MAX_VISIBLE_DOCS);
  }, [topicDocs, docsSearchTerm]);

  return (
    <Container fluid className="bg-light" style={{ height: '100vh' }}>
      <Row style={{ height: '50vh' }}>
        <Col md={12}>
          <div style={{ display: 'flex', gap: '8px', height: '50vh' }}>
            <div style={{ flex: 1, minWidth: 0 }}>
          {visualType === 'one-topic' ? (
            <PlotPersonaTopic
              update={plot}
              visualType={visualType}
              topic={topic}
              company={company}
              onRendered={resetApply}
              onClickData={handlePersonaClick}
              layout={{
                title: 'ペルソナの可視化',
                width: '100%',
                height: '50vh',
              }}
              config={{ responsive: true }}
              style={{ width: '100%', height: '50vh' }}
              className="bg-light"
            />
          ) : visualType === 'one-comp' ? (
            <PlotPersonaComp
              update={plot}
              visualType={visualType}
              topic={topic}
              company={company}
              onRendered={resetApply}
              layout={{
                title: 'ペルソナの可視化',
                width: '100%',
                height: '42vh',
              }}
              config={{ responsive: true }}
              style={{ width: '100%', height: '100%' }}
              className="bg-light"
            />
          ) : (
            <div>該当する表示がありません</div>
          )}
            </div>

            <div style={{ width: `${patentPanelWidth}px`, minWidth: `${patentPanelWidth}px` }}>
          <Card style={{ height: '50vh' }} className="border-info-subtle">
            <Card.Body className="py-2 px-2 d-flex flex-column">
              <div className="d-flex justify-content-between align-items-center mb-2">
                <div className="small text-muted">TOPIC別 文献</div>
                <Badge bg="secondary">{topicDocs.length}</Badge>
              </div>
              <div className="small text-muted mb-2">TOPIC {activeTopicId || '-'}</div>

              <InputGroup size="sm" className="mb-2">
                <Form.Control
                  placeholder="文献を検索"
                  value={docsSearchTerm}
                  onChange={(e) => setDocsSearchTerm(e.target.value)}
                />
              </InputGroup>

              {docsLoading && (
                <div className="small text-muted">
                  <Spinner size="sm" animation="border" className="me-2" />
                  読み込み中...
                </div>
              )}

              {!docsLoading && docsError && (
                <Alert variant="warning" className="mb-0 py-1 px-2 small">
                  {docsError}
                </Alert>
              )}

              {!docsLoading && !docsError && (
                <>
                  <div className="small text-muted mb-1">
                    {docsFiltered.length} / {topicDocs.length} 件
                  </div>
                  <ListGroup style={{ overflowY: 'auto', flex: 1 }}>
                    {docsFiltered.map((doc) => (
                      <ListGroup.Item key={doc.number} className="py-2 px-2">
                        <div className="small fw-bold">{doc.number}</div>
                        <div className="small">{doc.title || '(タイトルなし)'}</div>
                      </ListGroup.Item>
                    ))}
                    {docsFiltered.length === 0 && (
                      <ListGroup.Item className="small text-muted">
                        該当する文献はありません
                      </ListGroup.Item>
                    )}
                  </ListGroup>
                </>
              )}
            </Card.Body>
          </Card>
            </div>
          </div>
        </Col>
      </Row>

      <Row style={{ height: '50vh' }}>
        <Col md={6}>
          {visualType === 'one-topic' ? (
            <PlotPieA
              update={plot}
              visualType={visualType}
              topic={topic}
              company={company}
              onRendered={resetApply}
              layout={{
                title: '注目企業の業界に対する占有率',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          ) : visualType === 'one-comp' ? (
            <PlotPieB
              update={plot}
              visualType={visualType}
              topic={topic}
              company={company}
              onRendered={resetApply}
              onClickData={handlePieChartClick}
              layout={{
                title: '注目企業の業界に対する占有率',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          ) : (
            <div>該当する表示がありません</div>
          )}
        </Col>
        <Col md={6}>
          {visualType === 'one-topic' ? (
            <PlotBarChartA
              update={plot}
              visualType={visualType}
              topic={topic}
              onRendered={resetApply}
              data={[]}
              layout={{
                title: 'Fタームの分布',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          ) : (
            <PlotBarChartB
              update={plot}
              visualType={visualType}
              topic={topic}
              company={company}
              clickdata={clickData}
              onRendered={resetApply}
              data={[]}
              layout={{
                title: 'Fタームの分布',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          )}
        </Col>
      </Row>
      <Row className="h-100">
        <Col>
          {visualType === 'one-topic' ? (
            <ProposedVisualize
              topic={topic}
              clickData={clickCompanyData}
              layout={{
                title: '任意の位置へ移動するための提案',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          ) : (
            <br />
          )}
        </Col>
      </Row>
    </Container>
  );
};

export default Content;

